    // ─────────── فصل ۱: خانه اوبلونسکی ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "The Oblonsky Household", titlePersian = "خانه اوبلونسکی",
        paragraphs = listOf(
            StoryParagraph("All happy families are alike; each unhappy family is unhappy in its own way.", "همه خانواده‌های خوشبخت شبیه هم هستند؛ هر خانواده بدبختی به شیوه خودش بدبخت است."),
            StoryParagraph("With this sentence — perhaps the most famous opening in all of literature — Tolstoy announces the theme that will occupy him for the next eight hundred pages: the mystery of human happiness and the tragedy of its loss.", "تولستوی با این جمله — شاید مشهورترین آغاز در تمام ادبیات — مضمونی را اعلام می‌کند که هشتصد صفحه بعدی را به آن اختصاص می‌دهد: رمز خوشبختی انسان و تراژدی از دست دادنش."),
            StoryParagraph("The novel opens in the house of Prince Stepan Arkadyevich Oblonsky — Stiva, as everyone calls him — where a domestic catastrophe has just occurred.", "رمان در خانه شاهزاده استپان آرکادیویچ اوبلونسکی — استیوا، همانطور که همه صدایش می‌زنند — آغاز می‌شود، جایی که فاجعه‌ای خانوادگی تازه رخ داده است."),
            StoryParagraph("Stiva, a man of genial temperament and limitless capacity for self-indulgence, has been discovered in an affair with the French governess, and his wife, Dolly, has declared that she can no longer live with him.", "استیوا، مردی با خوی خوش‌مشرب و ظرفیت بی‌پایان برای لذت‌جویی، در رابطه‌ای با معلم سرخانه فرانسوی کشف شده و همسرش، دالی، اعلام کرده که دیگر نمی‌تواند با او زندگی کند."),
            StoryParagraph("Stiva himself is not a wicked man, nor even a particularly passionate one; he is simply a man who cannot help seeking pleasure wherever he finds it, and who cannot understand why anyone should make a fuss about it.", "خود استیوا مردی شرور نیست، و نه حتی به‌طور خاص پرشور؛ او فقط مردی است که نمی‌تواند از جستجوی لذت هر جا که پیدایش می‌کند خودداری کند و نمی‌فهمد چرا کسی باید سر و صدا راه بیندازد."),
            StoryParagraph("His philosophy of life — if it can be called a philosophy — is summed up in his favorite saying: 'Everything will sort itself out.'", "فلسفه زندگی‌اش — اگر بتوان فلسفه نامیدش — در جمله مورد علاقه‌اش خلاصه می‌شود: «همه چیز خودش حل می‌شود.»"),
            StoryParagraph("But things do not sort themselves out, as Stiva is about to discover; the arrival of his sister, Anna Karenina, will set in motion a chain of events that will destroy not only his household but hers as well.", "اما همه چیز خودش حل نمی‌شود، همانطور که استیوا در شرف کشفش است؛ ورود خواهرش، آنا کارنینا، زنجیره‌ای از رویدادها را به حرکت درمی‌آورد که نه فقط خانه او بلکه خانه خودش را نیز نابود می‌کند."),
            StoryParagraph("Anna arrives in Moscow from Petersburg, summoned by Stiva to help reconcile him with Dolly, and from the moment of her appearance, she brings with her a vitality, a charm, a warmth that no one in the household can resist.", "آنا به دعوت استیوا از پترزبورگ به مسکو می‌آید تا کمکش کند با دالی آشتی کند و از لحظه ظهورش، سرزندگی، جذابیت، گرمایی با خود می‌آورد که هیچ‌کس در خانه نمی‌تواند مقاومتش کند."),
            StoryParagraph("She is beautiful, yes — but her beauty is not the cold beauty of a statue; it is the living beauty of a woman who is fully, passionately, radiantly alive.", "او زیباست، بله — اما زیبایی‌اش زیبایی سرد مجسمه نیست؛ زیبایی زنده زنی است که کاملاً، پرشور، درخشان زنده است."),
            StoryParagraph("There is something in her eyes, something in her smile, something in the very way she moves, that makes everyone around her feel more alive themselves.", "چیزی در چشمانش، چیزی در لبخندش، چیزی در همان شیوه حرکتش هست که هر کسی را در اطرافش بیشتر زنده حس می‌کند."),
            StoryParagraph("She reconciles Stiva and Dolly with a tact and a tenderness that astonishes everyone, and in doing so, she reveals the fundamental quality of her character: an almost infinite capacity for sympathy with the suffering of others.", "او استیوا و دالی را با تدبیر و لطافتی که همه را حیرت‌زده می‌کند آشتی می‌دهد و در این کار، کیفیت بنیادین شخصیتش را آشکار می‌کند: ظرفیتی تقریباً بی‌نهایت برای همدلی با رنج دیگران."),
            StoryParagraph("This sympathy, this ability to feel what others feel, will be both her glory and her doom; it is what makes her lovable, and it is what makes her vulnerable.", "این همدلی، این توانایی حس کردن آنچه دیگران حس می‌کنند، هم شکوه او خواهد بود و هم سرنوشتش؛ چیزی است که او را دوست‌داشتنی می‌کند و چیزی است که او را آسیب‌پذیر می‌کند."),
            StoryParagraph("At the ball that evening, Anna meets Count Vronsky, a young officer of aristocratic family and brilliant prospects, and something passes between them that neither can name.", "آن شب در مهمانی رقص، آنا با کنت ورونسکی آشنا می‌شود، افسر جوانی از خانواده‌ای اشرافی با آینده‌ای درخشان و چیزی میان آنها رد می‌شود که هیچ‌کدام نمی‌توانند نامش را ببرند."),
            StoryParagraph("Vronsky had been courting Kitty Shcherbatskaya, Dolly's younger sister, and Kitty had believed — had been encouraged to believe — that he would propose to her.", "ورونسکی خواستگاری کیتی شچرباتسکایا بود، خواهر کوچک‌تر دالی و کیتی باور کرده بود — تشویق شده بود باور کند — که او به او پیشنهاد ازدواج می‌دهد."),
            StoryParagraph("But from the moment Vronsky sees Anna at the ball, everything changes; he cannot take his eyes off her, and Kitty, watching him watch her, understands in an instant that she has been abandoned.", "اما از لحظه‌ای که ورونسکی آنا را در مهمانی می‌بیند، همه چیز تغییر می‌کند؛ نمی‌تواند چشمانش را از او بردارد و کیتی، در حال تماشای او که او را تماشا می‌کند، در یک لحظه می‌فهمد که رها شده."),
            StoryParagraph("The scene at the ball is one of the most famous in all of Tolstoy's work: the beautiful Anna in her black gown, the desperate Kitty in her pink, the unseeing Vronsky between them.", "صحنه در مهمانی یکی از مشهورترین صحنه‌های تمام آثار تولستوی است: آنا زیبا در لباس سیاهش، کیتی درمانده در صورتیش، ورونسکی نابینا در میان آنها."),
            StoryParagraph("Anna, aware of what she has done, aware of the pain she has caused, goes to Kitty the next day to apologize, but the apology only makes things worse, for it confirms what Kitty already knows.", "آنا که آگاه است از آنچه کرده، آگاه از دردی که ایجاد کرده، روز بعد به نزد کیتی می‌رود تا عذرخواهی کند، اما عذرخواهی فقط اوضاع را بدتر می‌کند، چون تأیید می‌کند آنچه کیتی از قبل می‌داند."),
            StoryParagraph("Anna returns to Petersburg that night, and Vronsky, unable to bear the thought of losing her, follows her on the same train.", "آنا آن شب به پترزبورگ برمی‌گردد و ورونسکی، که تحمل فکر از دست دادنش را ندارد، در همان قطار دنبالش می‌کند."),
            StoryParagraph("On the train, in the snow and the darkness, Anna experiences a moment of terrifying clarity: she knows that she is standing at the edge of an abyss, and she knows that she is going to fall.", "در قطار، در برف و تاریکی، آنا لحظه‌ای از وضوح هولناک را تجربه می‌کند: می‌داند که در لبه پرتگاهی ایستاده و می‌داند که خواهد افتاد."),
            StoryParagraph("'What am I doing?' she asks herself. 'What is going to happen to me? I do not know, but I cannot stop.'", "از خودش می‌پرسد: «چه می‌کنم؟ بر سرم چه خواهد آمد؟ نمی‌دانم، اما نمی‌توانم بایستم.»"),
            StoryParagraph("She arrives home to her husband, Alexei Karenin, and her beloved son, Seryozha, and for a moment she thinks she can resume her old life, can pretend that nothing has happened.", "به خانه می‌رسد نزد همسرش، آلکسی کارنین و پسر محبوبش، سریوژا و لحظه‌ای فکر می‌کند می‌تواند زندگی قبلی‌اش را از سر بگیرد، می‌تواند تظاهر کند هیچ اتفاقی نیفتاده."),
            StoryParagraph("But Vronsky is in Petersburg too, and he begins to appear everywhere she goes, and each appearance weakens her resistance, and each weakness makes the next appearance more dangerous.", "اما ورونسکی هم در پترزبورگ است و شروع می‌کند به ظاهر شدن در هر جایی که او می‌رود و هر ظهور مقاومتش را ضعیف‌تر می‌کند و هر ضعف ظهور بعدی را خطرناک‌تر."),
            StoryParagraph("Karenin, meanwhile, notices nothing, or pretends to notice nothing; he is absorbed in his work, in his ambition, in his careful construction of a public career.", "کارنین در همین حال چیزی متوجه نمی‌شود، یا تظاهر می‌کند چیزی متوجه نمی‌شود؛ غرق کارش است، در جاه‌طلبی‌اش، در ساخت دقیق یک زندگی حرفه‌ای."),
            StoryParagraph("He is not a bad man, Karenin, but he is a man without warmth, without imagination, without any understanding of the human heart.", "او مرد بدی نیست، کارنین، اما مردی است بدون گرمی، بدون تخیل، بدون هیچ درکی از قلب انسان."),
            StoryParagraph("To him, marriage is an institution, a duty, a matter of propriety; to Anna, marriage is a matter of life and death.", "برای او، ازدواج نهادی است، وظیفه‌ای است، مسئله‌ای از آبرو؛ برای آنا، ازدواج مسئله‌ای از زندگی و مرگ است."),
            StoryParagraph("This incompatibility, which has been present since the beginning of their marriage, will now become the engine of the tragedy that is about to unfold.", "این ناسازگاری که از آغاز ازدواجشان وجود داشته، حالا موتور تراژدی خواهد شد که در شرف رخ دادن است."),
            StoryParagraph("And so the first chapter ends with Anna poised between her old life and her new, between the woman she has been and the woman she is becoming, between a husband she does not love and a man she cannot resist.", "و اینگونه فصل اول با آنا در تعلیق میان زندگی قبلی و جدیدش پایان می‌یابد، میان زنی که بوده و زنی که در حال شدن است، میان همسری که دوستش ندارد و مردی که نمی‌تواند مقاومتش کند."),
            StoryParagraph("The famous opening line is now revealed in all its irony: this family, the Karenins, is unhappy in its own way, and the way of its unhappiness will be the way of the entire novel.", "جمله آغازین مشهور حالا در تمام طعنه‌اش آشکار می‌شود: این خانواده، کارنین‌ها، به شیوه خودش بدبخت است و شیوه بدبختی‌اش، شیوه تمام رمان خواهد بود."),
            StoryParagraph("Tolstoy does not judge; he observes. He does not preach; he shows. And what he shows us, in the first chapter of his greatest novel, is a woman walking, with open eyes, into the abyss.", "تولستوی قضاوت نمی‌کند؛ مشاهده می‌کند. موعظه نمی‌کند؛ نشان می‌دهد. و آنچه در فصل اول بزرگ‌ترین رمانش به ما نشان می‌دهد، زنی است که با چشمان باز به سمت پرتگاه می‌رود."),
            StoryParagraph("The rest of the novel will be the story of that falling, and of the impossible hope that somewhere, somehow, someone will be there to catch her.", "بقیه رمان داستان آن افتادن خواهد بود و امید غیرممکن که جایی، به نحوی، کسی آنجا خواهد بود که بگیردش.")
        )
    )

    // ─────────── فصل ۲: ورونسکی ───────────
    private fun chapter2() = StoryChapter(
        number = 2, title = "Vronsky", titlePersian = "ورونسکی",
        paragraphs = listOf(
            StoryParagraph("Count Alexei Kirillovich Vronsky is, in the language of his world, a brilliant young man: a military officer of distinguished family, a man of wealth, a man of charm, a man of the future.", "کنت آلکسی کیریلیویچ ورونسکی، در زبان دنیایش، جوانی درخشان است: افسر نظامی از خانواده‌ای برجسته، مردی ثروتمند، مردی جذاب، مردی از آینده."),
            StoryParagraph("He is also, though no one around him will admit it, a man utterly without substance: he has no convictions, no ambitions beyond the next promotion, no interests beyond the next pleasure.", "او همچنین، هرچند هیچ‌کس در اطرافش اعتراف نخواهد کرد، مردی کاملاً بدون جوهر است: هیچ اعتقادی ندارد، هیچ جاه‌طلبی فراتر از ترفیع بعدی، هیچ علاقه‌ای فراتر از لذت بعدی."),
            StoryParagraph("He has spent his life doing what men of his class are expected to do: serving in the army, attending balls, enjoying the favors of women who find him irresistible, and never once asking himself what any of it was for.", "زندگی‌اش را صرف انجام کارهایی کرده که از مردان طبقه‌اش انتظار می‌رود: خدمت در ارتش، شرکت در مهمانی‌های رقص، لذت بردن از لطف زنانی که او را مقاومت‌ناپذیر می‌یابند و هرگز یک بار هم از خودش نپرسیده که اینها برای چه هستند."),
            StoryParagraph("Before meeting Anna, he had been courting Kitty Shcherbatskaya, the younger daughter of a respectable Moscow family, without any real intention of marrying her.", "پیش از ملاقات با آنا، مشغول خواستگاری کیتی شچرباتسکایا بود، دختر کوچک‌تر خانواده‌ای محترم در مسکو، بدون هیچ قصد واقعی برای ازدواج با او."),
            StoryParagraph("Kitty had believed, had been encouraged to believe, that he loved her; and Vronsky, who was not a cruel man, had allowed her to believe it because it pleased him to be loved.", "کیتی باور کرده بود، تشویق شده بود باور کند، که او دوستش دارد؛ و ورونسکی که مردی بی‌رحم نبود، اجازه داده بود باورش شود چون خوشحالش می‌کرد که دوست داشته شود."),
            StoryParagraph("This is the first clue to Vronsky's character: he is not evil, but he is thoughtless. He does not set out to hurt others; he simply does not think about them at all.", "این اولین سرنخ شخصیت ورونسکی است: او شرور نیست، اما بی‌فکر است. قصد ندارد به دیگران آسیب بزند؛ فقط اصلاً به آنها فکر نمی‌کند."),
            StoryParagraph("When he meets Anna at the Moscow ball, something in him — something he did not know existed — awakens for the first time in his life.", "وقتی در مهمانی مسکو با آنا آشنا می‌شود، چیزی در او — چیزی که نمی‌دانست وجود دارد — برای اولین بار در زندگی‌اش بیدار می‌شود."),
            StoryParagraph("He is attracted to her, of course; any man would be. But what he feels is not merely attraction; it is something more like recognition, as though he has found the answer to a question he has never known how to ask.", "البته که جذب او می‌شود؛ هر مردی می‌شد. اما آنچه حس می‌کند فقط جذابیت نیست؛ چیزی بیشتر شبیه به تشخیص است، گویی پاسخ پرسشی را یافته که هرگز نمی‌دانست چگونه بپرسد."),
            StoryParagraph("He follows her to Petersburg, not with a plan, not with a purpose, but simply because he cannot bear the thought of her being somewhere he is not.", "او به پترزبورگ دنبالش می‌رود، نه با نقشه، نه با هدف، بلکه فقط چون نمی‌تواند تحمل کند فکر اینکه او جایی باشد که او نیست."),
            StoryParagraph("At first, Anna resists. She is a married woman, a mother, a woman of principle, and she knows what is at stake.", "در ابتدا، آنا مقاومت می‌کند. زنی متأهل است، مادری است، زنی با اصول و می‌داند چه چیزی در خطر است."),
            StoryParagraph("But Vronsky is persistent, and Anna is lonely, and Karenin — her husband — is a man she has never been able to love, perhaps because he has never given her anything to love.", "اما ورونسکی پافشار است، آنا تنهاست و کارنین — همسرش — مردی است که هرگز نتوانسته دوستش داشته باشد، شاید چون او هرگز چیزی برای دوست داشتن به او نداده."),
            StoryParagraph("Their affair begins, as such things often begin, not with a single decision but with a thousand small concessions, each of which seemed unimportant at the time and each of which led to the next.", "رابطه‌شان آغاز می‌شود، همانطور که چنین چیزهایی اغلب آغاز می‌شوند، نه با یک تصمیم واحد بلکه با هزار امتیاز کوچک که هر یک در زمان خودش بی‌اهمیت به نظر می‌رسید و هر یک به بعدی می‌رسید."),
            StoryParagraph("Tolstoy, in depicting their passion, does not romanticize it; he shows it as it is: consuming, irrational, destructive, and utterly irresistible.", "تولستوی در به تصویر کشیدن شورشان، رمانتیکش نمی‌کند؛ آن را همانطور که هست نشان می‌دهد: همه‌چیزخوار، غیرعقلانی، مخرب و کاملاً مقاومت‌ناپذیر."),
            StoryParagraph("Anna, in the first months of the affair, is happy — as happy as she has ever been — and her happiness is all the more terrible because it is built on a lie.", "آنا، در ماه‌های اول رابطه، خوشحال است — به همان اندازه که تا حالا بوده — و خوشحالی‌اش از این هم هولناک‌تر است چون بر دروغی بنا شده."),
            StoryParagraph("She lies to her husband, she lies to her friends, she lies to her society; and each lie takes something from her, something she will never be able to reclaim.", "به همسرش دروغ می‌گوید، به دوستانش دروغ می‌گوید، به جامعه‌اش دروغ می‌گوید؛ و هر دروغ چیزی از او می‌گیرد، چیزی که هرگز نمی‌تواند بازش گرداند."),
            StoryParagraph("Meanwhile, Karenin, who is not as blind as he seems, begins to suspect. But he does not confront his wife; he does not demand an explanation; he simply withdraws into himself.", "در همین حال، کارنین که آنقدرها هم که به نظر می‌رسد کور نیست، شروع به شک می‌کند. اما با همسرش روبرو نمی‌شود؛ توضیح نمی‌خواهد؛ فقط به درون خودش عقب می‌کشد."),
            StoryParagraph("This is Karenin's tragedy: he is a man of principle without passion, of duty without warmth, of rectitude without sympathy. He knows what is right, but he does not know how to love.", "این تراژدی کارنین است: او مردی است با اصول بدون شور، با وظیفه بدون گرمی، با درستی بدون همدلی. می‌داند چه درست است، اما نمی‌داند چگونه عشق بورزد."),
            StoryParagraph("When Anna finally confesses — for confess she does, in a scene of extraordinary cruelty and honesty — Karenin's response is not rage but calculation.", "وقتی آنا بالاخره اعتراف می‌کند — چون اعتراف می‌کند، در صحنه‌ای از بی‌رحمی و صداقت فوق‌العاده — واکنش کارنین خشم نیست بلکه محاسبه است."),
            StoryParagraph("He considers the matter as he would consider a legal case, weighing the consequences, evaluating the options, selecting the course of action most likely to preserve his position.", "موضوع را همانطور که یک پرونده حقوقی را بررسی می‌کند بررسی می‌کند، پیامدها را می‌سنجد، گزینه‌ها را ارزیابی می‌کند، مسیری را انتخاب می‌کند که احتمالاً جایگاهش را حفظ می‌کند."),
            StoryParagraph("'I have considered your confession,' he says at last, 'and I have decided upon the following course of action.'", "بالاخره می‌گوید: «اعتراف تو را بررسی کرده‌ام و درباره شیوه عمل زیر تصمیم گرفته‌ام.»"),
            StoryParagraph("He delivers his verdict like a judge delivering a sentence: the marriage will continue; appearances will be maintained; Anna will not see Vronsky again; and she will not, under any circumstances, be permitted to leave.", "حکمش را مثل قاضی صادر می‌کند: ازدواج ادامه می‌یابد؛ ظاهرها حفظ می‌شود؛ آنا دیگر ورونسکی را نمی‌بیند؛ و تحت هیچ شرایطی اجازه رفتن ندارد."),
            StoryParagraph("'You will remain in this house,' he says, 'and you will conduct yourself in a manner appropriate to your position. Anything else is out of the question.'", "می‌گوید: «در این خانه می‌مانی و به شیوه‌ای مناسب جایگاهت رفتار می‌کنی. هر چیز دیگری منتفی است.»"),
            StoryParagraph("Anna, who had braced herself for anger, for violence, for anything except this terrible, icelike calm, is shattered by his response.", "آنا که خودش را برای خشم، برای خشونت، برای هر چیزی جز این آرامش هولناک و یخ‌مانند آماده کرده بود، با پاسخ او خرد می‌شود."),
            StoryParagraph("She realizes, in that moment, that her husband does not love her — has never loved her — and that the marriage she has been trying to preserve has always been, in truth, a prison.", "در آن لحظه می‌فهمد که همسرش او را دوست ندارد — هرگز دوستش نداشته — و ازدواجی که سعی کرده حفظش کند در حقیقت همیشه زندان بوده."),
            StoryParagraph("And so she chooses: she leaves Karenin, she leaves her son, she leaves her position, she leaves everything she has known, to be with Vronsky.", "و اینگونه انتخاب می‌کند: کارنین را ترک می‌کند، پسرش را ترک می‌کند، جایگاهش را ترک می‌کند، هر چیزی را که شناخته ترک می‌کند تا با ورونسکی باشد."),
            StoryParagraph("This is the moment of Anna's fall, and it is also the moment of her greatness; for in choosing love over propriety, she chooses life over death, and she knows what it will cost.", "این لحظه سقوط آناست و همچنین لحظه عظمت اوست؛ چون با انتخاب عشق بر آبرو، زندگی را بر مرگ انتخاب می‌کند و می‌داند چه هزینه‌ای خواهد داشت."),
            StoryParagraph("But Vronsky, who has never had to sacrifice anything in his life, does not understand the magnitude of what she has done for him.", "اما ورونسکی که در عمرش هرگز مجبور نبوده چیزی فدا کند، عظمت آنچه او برایش کرده را نمی‌فهمد."),
            StoryParagraph("He loves her — he believes he loves her — but his love is not strong enough to bear the weight of her sacrifice.", "او دوستش دارد — باور دارد که دوستش دارد — اما عشقش به اندازه کافی قوی نیست که وزن فداکاری او را تحمل کند."),
            StoryParagraph("And so the tragedy accelerates: two people who love each other, bound together by a love that is destroying them both, unable to live together and unable to live apart.", "و اینگونه تراژدی شتاب می‌گیرد: دو نفر که یکدیگر را دوست دارند، بسته به هم توسط عشقی که هر دو را نابود می‌کند، ناتوان از زندگی با هم و ناتوان از زندگی جدا."),
            StoryParagraph("This is the unbearable tension at the heart of Anna Karenina: that love, which should be the greatest good, becomes the greatest evil when it is placed in a world that cannot support it.", "این همان کشمکش غیرقابل تحمل در قلب آنا کارنیناست: عشق که باید بزرگ‌ترین خیر باشد، بزرگ‌ترین شر می‌شود وقتی در دنیایی قرار می‌گیرد که نمی‌تواند تحملش کند."),
            StoryParagraph("Vronsky is not the villain of the novel, as some readers have thought; he is simply a man out of his depth, a man who has been given a responsibility too great for his character.", "ورونسکی شرور رمان نیست، همانطور که برخی خوانندگان فکر کرده‌اند؛ او فقط مردی است خارج از عمقش، مردی که مسئولیتی بزرگ‌تر از شخصیتش به او داده شده."),
            StoryParagraph("And Anna, who has given him everything, will discover that everything is not enough; that love, without a world to sustain it, is not enough; that even the greatest passion cannot survive in a vacuum.", "و آنا که همه چیز به او داده، کشف خواهد کرد که همه چیز کافی نیست؛ که عشق، بدون دنیایی که حفظش کند، کافی نیست؛ که حتی بزرگ‌ترین شور نمی‌تواند در خلا زنده بماند.")
        )
    )

    // ─────────── فصل ۳: لوین ───────────
    private fun chapter3() = StoryChapter(
        number = 3, title = "Levin", titlePersian = "لوین",
        paragraphs = listOf(
            StoryParagraph("While Anna falls, another story rises; while one marriage is destroyed, another is built; for Tolstoy, the story of Anna and the story of Levin are not two stories but one.", "در حالی که آنا سقوط می‌کند، داستان دیگری بالا می‌رود؛ در حالی که یک ازدواج نابود می‌شود، ازدواج دیگری ساخته می‌شود؛ برای تولستوی، داستان آنا و داستان لوین دو داستان نیستند بلکه یک داستان است."),
            StoryParagraph("Konstantin Dmitrievich Levin is a landowner, a man of the countryside, a man who believes in work, in family, in the simple virtues that the aristocrats of Petersburg have long forgotten.", "کنستانتین دمیتریویچ لوین مالکی است، مردی از روستا، مردی که به کار باور دارد، به خانواده، به فضیلت‌های ساده‌ای که اشراف پترزبورگ مدت‌ها پیش فراموش کرده‌اند."),
            StoryParagraph("He is not brilliant, not charming, not elegant; he is awkward, shy, given to long silences and sudden angers; and yet there is in him a depth, an honesty, an integrity that none of the other characters possess.", "او درخشان نیست، جذاب نیست، ظریف نیست؛ دست‌وپا چلفتی است، خجالتی، مستعد سکوت‌های طولانی و خشم‌های ناگهانی؛ و با این حال عمقی در او هست، صداقتی، درستی‌ای که هیچ‌یک از شخصیت‌های دیگر ندارند."),
            StoryParagraph("He loves Kitty Shcherbatskaya, Dolly's younger sister, and he has loved her for years, ever since they were children playing together on their family estates.", "او کیتی شچرباتسکایا را دوست دارد، خواهر کوچک‌تر دالی و سال‌هاست دوستش دارد، از همان زمان که در کودکی در املاک خانوادگی‌شان با هم بازی می‌کردند."),
            StoryParagraph("He has come to Moscow to propose to her — this awkward, serious man — and he is prepared to offer her everything he has: his name, his estate, his life, his future.", "به مسکو آمده تا به او پیشنهاد ازدواج دهد — این مرد دست‌وپا چلفتی جدی — و آماده است هر چه دارد به او عرضه کند: نامش، ملکش، زندگی‌اش، آینده‌اش."),
            StoryParagraph("But Kitty, who is young, who is foolish, who has been dazzled by the glitter of Petersburg, refuses him; she is waiting for Vronsky, or for someone like Vronsky, someone brilliant and exciting and utterly without depth.", "اما کیتی که جوان است، احمق است، توسط درخشش پترزبورگ خیره شده، ردش می‌کند؛ منتظر ورونسکی است، یا کسی مثل ورونسکی، کسی درخشان و هیجان‌انگیز و کاملاً بدون عمق."),
            StoryParagraph("Levin accepts her refusal with the dignity of a man who has been hurt before and knows how to bear it, and he returns to his estate, where he works and thinks and waits.", "لوین ردش را با وقار مردی می‌پذیرد که قبلاً زخم خورده و می‌داند چگونه تحملش کند و به ملکش برمی‌گردد، جایی که کار می‌کند و فکر می‌کند و منتظر می‌ماند."),
            StoryParagraph("His estate is his world, and it is a world of extraordinary richness: fields of wheat and clover, forests of birch and pine, peasants who work the land with the ancient rhythms of their ancestors.", "ملکش دنیای اوست و دنیایی با غنای فوق‌العاده است: مزارع گندم و شبدر، جنگل‌های توس و کاج، دهقانی که زمین را با ریتم‌های کهن نیاکانشان کار می‌کنند."),
            StoryParagraph("Levin works beside them, not as a master but as a fellow laborer, and in the sweat of his brow, he finds a kind of peace that none of the other characters ever know.", "لوین کنار آنها کار می‌کند، نه به عنوان ارباب بلکه به عنوان همکار و در عرق پیشانی‌اش، نوعی آرامش می‌یابد که هیچ‌یک از شخصیت‌های دیگر هرگز نمی‌شناسند."),
            StoryParagraph("But peace is not the same as happiness, and Levin is not happy; he is tormented by the great questions that Tolstoy himself was tormented by.", "اما آرامش همان خوشبختی نیست و لوین خوشبخت نیست؛ توسط پرسش‌های بزرگی عذاب می‌کشد که خود تولستوی از آنها عذاب می‌کشید."),
            StoryParagraph("Why are we here? What is the meaning of life? How should we live? What is the purpose of all this striving and suffering and dying?", "چرا اینجاییم؟ معنای زندگی چیست؟ چگونه باید زندگی کنیم؟ هدف تمام این تلاش و رنج و مردن چیست؟"),
            StoryParagraph("He reads philosophy, and philosophy gives him arguments but no answers; he reads science, and science tells him how things work but not why they matter.", "فلسفه می‌خواند و فلسفه استدلال به او می‌دهد اما نه پاسخ؛ علم می‌خواند و علم به او می‌گوید چیزها چگونه کار می‌کنند اما نه چرا مهم‌اند."),
            StoryParagraph("He tries to live as the peasants live, to accept the simple faith that they accept, but his intelligence will not let him; he cannot believe what he cannot understand.", "تلاش می‌کند مثل دهقانان زندگی کند، ایمان ساده‌ای را بپذیرد که آنها می‌پذیرند، اما هوشش اجازه نمی‌دهد؛ نمی‌تواند آنچه را نمی‌فهمد باور کند."),
            StoryParagraph("And yet, in the midst of his doubt, there are moments of grace: moments when the sky opens, when the fields shimmer with light, when he feels, for an instant, that everything is right.", "و با این حال، در میان شکش، لحظات فیضی هست: لحظاتی که آسمان باز می‌شود، مزارع با نور می‌درخشند، لحظاتی که برای یک آن حس می‌کند همه چیز درست است."),
            StoryParagraph("Meanwhile, Kitty, having been rejected by Vronsky, having been humiliated, having been brought to the edge of despair, retreats to a German spa to recover.", "در همین حال، کیتی که توسط ورونسکی رد شده، تحقیر شده، به لبه ناامیدی رسیده، به آبگرمی آلمانی عقب‌نشینی می‌کند تا بهبود یابد."),
            StoryParagraph("There, she meets Varenka, a young woman of such simple and radiant goodness that Kitty is at first bewildered and then transformed.", "آنجا، با وارنکا آشنا می‌شود، زن جوانی با چنان نیکی ساده و درخشان که کیتی ابتدا گیج و بعد دگرگون می‌شود."),
            StoryParagraph("Varenka has no beauty, no wealth, no position; she has only goodness, only kindness, only a capacity for love that Kitty has never encountered before.", "وارنکا زیبایی ندارد، ثروتی ندارد، جایگاهی ندارد؛ تنها نیکی دارد، تنها مهربانی، تنها ظرفیتی برای عشق که کیتی هرگز قبلاً با آن روبرو نشده."),
            StoryParagraph("Under Varenka's influence, Kitty begins to grow; she begins to understand that the things she valued — beauty, brilliance, admiration — are not the things that matter.", "زیر تأثیر وارنکا، کیتی شروع به رشد می‌کند؛ شروع به فهمیدن این می‌کند که چیزهایی که ارزش می‌گذاشت — زیبایی، درخشندگی، تحسین — چیزهایی نیستند که مهم‌اند."),
            StoryParagraph("When she returns to Russia, she is not the same Kitty who left; she has suffered, and suffering has taught her what happiness could not.", "وقتی به روسیه برمی‌گردد، همان کیتی نیست که رفته بود؛ رنج کشیده و رنج چیزی به او آموخته که خوشبختی نمی‌توانست."),
            StoryParagraph("Levin, seeing her again, sees the change; and he loves her not less but more, for he sees now that she has become the woman he always knew she could be.", "لوین، در دیدن دوباره‌اش، تغییر را می‌بیند؛ و نه کمتر بلکه بیشتر دوستش دارد، چون حالا می‌بیند زنی شده که همیشه می‌دانست می‌تواند باشد."),
            StoryParagraph("He proposes again, and this time she accepts, and their courtship — awkward, tender, full of misunderstandings and reconciliations — is one of the most beautifully rendered in all of literature.", "دوباره خواستگاری می‌کند و این بار می‌پذیرد و خواستگاری آنها — دست‌وپا چلفتی، لطیف، پر از سوءتفاهم و آشتی — یکی از زیباترین صحنه‌های تمام ادبیات است."),
            StoryParagraph("Their wedding is a sacrament, not a social event; Levin, who doubts everything, finds himself praying during the ceremony, and the prayer is not an argument but a cry.", "عروسی‌شان آیینی مقدس است، نه رویدادی اجتماعی؛ لوین که به همه چیز شک دارد، در طول مراسم خودش را در حال دعا کردن می‌یابد و دعا استدلال نیست بلکه فریادی است."),
            StoryParagraph("Their marriage, unlike Anna's, is grounded in work, in honesty, in the daily, unglamorous labor of building a life together.", "ازدواج آنها، برخلاف ازدواج آنا، در کار ریشه دارد، در صداقت، در کار روزانه و بی‌جذابیت ساختن زندگی با هم."),
            StoryParagraph("They argue, they misunderstand each other, they hurt each other; but they also forgive, they also grow, they also love.", "دعوا می‌کنند، یکدیگر را نمی‌فهمند، به هم آسیب می‌زنند؛ اما هم می‌بخشند، هم رشد می‌کنند، هم عشق می‌ورزند."),
            StoryParagraph("And when Kitty gives birth to their first child, Levin, watching the agony of labor, experiences a transformation that no philosophy could have given him.", "و وقتی کیتی اولین فرزندشان را به دنیا می‌آورد، لوین، در تماشای عذاب زایمان، دگرگونی‌ای را تجربه می‌کند که هیچ فلسفه‌ای نمی‌توانست به او بدهد."),
            StoryParagraph("He understands, in that moment, that life is not a problem to be solved but a mystery to be lived; that the meaning is not in the answer but in the asking.", "در آن لحظه می‌فهمد که زندگی مسئله‌ای نیست که حل شود بلکه رمزی است که باید زندگی شود؛ معنا در پاسخ نیست بلکه در پرسیدن است."),
            StoryParagraph("This, for Tolstoy, is the answer that Anna never finds: not a solution to the riddle of existence, but the courage to live without one.", "این، برای تولستوی، پاسخی است که آنا هرگز نمی‌یابد: نه راه‌حلی برای معمای وجود، بلکه جرات زندگی کردن بدون یکی."),
            StoryParagraph("Levin and Kitty are not happy because they have no problems; they are happy because they have found something worth struggling for, something worth suffering for, something worth dying for.", "لوین و کیتی خوشبخت نیستند چون مشکلی ندارند؛ خوشبخت هستند چون چیزی یافته‌اند که ارزش جنگیدن دارد، چیزی که ارزش رنج کشیدن دارد، چیزی که ارزش مردن دارد."),
            StoryParagraph("And their happiness is not the end of the novel but its counterpoint, its promise, its hope.", "و خوشبختی آنها پایان رمان نیست بلکه کنترپوان آن است، وعده‌اش، امیدش."),
            StoryParagraph("Tolstoy gives us both stories — Anna's and Levin's — because he wants us to understand that there is no single answer to the question of how to live.", "تولستوی هر دو داستان را به ما می‌دهد — آنا و لوین — چون می‌خواهد ما بفهمیم که هیچ پاسخ واحدی به پرسش چگونه زندگی کردن وجود ندارد."),
            StoryParagraph("There is only the choice, and the consequence, and the terrible, beautiful responsibility of being human.", "تنها انتخاب هست و پیامد و مسئولیت هولناک و زیبای انسان بودن."),
            StoryParagraph("Anna chooses passion, and she is destroyed; Levin chooses work, and he is saved. But the novel does not condemn one and bless the other; it simply shows us what happens.", "آنا شور را انتخاب می‌کند و نابود می‌شود؛ لوین کار را انتخاب می‌کند و نجات می‌یابد. اما رمان یکی را محکوم نمی‌کند و دیگری را برکت نمی‌دهد؛ فقط به ما نشان می‌دهد چه اتفاقی می‌افتد."),
            StoryParagraph("And in that showing, we find wisdom: not the wisdom of a rule to follow, but the wisdom of a life to live.", "و در آن نشان دادن، حکمتی می‌یابیم: نه حکمت قاعده‌ای که دنبال شود، بلکه حکمت زندگی‌ای که زندگی شود.")
        )
    )

    // ─────────── فصل ۴: سقوط ───────────
    private fun chapter4() = StoryChapter(
        number = 4, title = "The Fall", titlePersian = "سقوط",
        paragraphs = listOf(
            StoryParagraph("After Anna leaves Karenin, after she abandons her son, after she gives up everything for Vronsky, she discovers that the world will not let her go.", "بعد از اینکه آنا کارنین را ترک می‌کند، بعد از اینکه پسرش را رها می‌کند، بعد از اینکه همه چیز را برای ورونسکی رها می‌کند، کشف می‌کند که دنیا رهایش نمی‌کند."),
            StoryParagraph("In Russia in the 1870s, a woman who leaves her husband for another man is not merely criticized; she is cast out. She is not received; she is not spoken to; she ceases, in effect, to exist.", "در روسیه دهه ۱۸۷۰، زنی که شوهرش را برای مرد دیگری ترک می‌کند، فقط مورد انتقاد قرار نمی‌گیرد؛ طرد می‌شود. پذیرفته نمی‌شود؛ با او صحبت نمی‌شود؛ در واقع، وجودش متوقف می‌شود."),
            StoryParagraph("Anna had known this, in the abstract, before she left; but knowledge in the abstract is not the same as knowledge in the flesh, and the reality is much worse than she had imagined.", "آنا این را در انتزاع می‌دانست، پیش از رفتن؛ اما دانش در انتزاع با دانش در تن یکی نیست و واقعیت بسیار بدتر از آن است که تصور کرده بود."),
            StoryParagraph("She and Vronsky travel to Italy, hoping to escape the judgments of Petersburg society, but judgment follows them; it is carried in the air they breathe, in the letters they receive, in the silence of those who will not write.", "او و ورونسکی به ایتالیا سفر می‌کنند، به امید گریز از قضاوت‌های جامعه پترزبورگ، اما قضاوت دنبالشان می‌آید؛ در هوایی که نفس می‌کشند، در نامه‌هایی که می‌گیرند، در سکوت کسانی که نمی‌نویسند."),
            StoryParagraph("Vronsky, who has never had to give up anything, finds the isolation difficult; Anna, who has given up everything, finds it unbearable.", "ورونسکی که هرگز مجبور نبوده چیزی فدا کند، انزوا را دشوار می‌یابد؛ آنا که همه چیز را فدا کرده، آن را غیرقابل تحمل می‌یابد."),
            StoryParagraph("Their love, which had seemed so strong in Moscow, begins to crack under the pressure of their solitude; they have each other, and only each other, and this is too much for any two people to bear.", "عشقشان که در مسکو اینقدر قوی به نظر می‌رسید، شروع به ترک خوردن می‌کند زیر فشار تنهایی‌شان؛ آنها فقط یکدیگر را دارند و فقط یکدیگر را و این برای هیچ دو نفری بیش از حد سنگین است."),
            StoryParagraph("Anna, in particular, suffers: she has lost her son, her position, her friends, her very identity; she has become, in the eyes of the world, not Anna Karenina but merely 'Vronsky's mistress.'", "آنا به‌ویژه رنج می‌کشد: پسرش را از دست داده، جایگاهش را، دوستانش را، هویت خودش را؛ در چشمان دنیا شده نه آنا کارنینا بلکه فقط «معشوقه ورونسکی.»"),
            StoryParagraph("She tries to fill the void with reading, with charity, with the construction of a hospital on Vronsky's estate; but nothing fills it, because nothing can replace what she has lost.", "تلاش می‌کند پوچی را با خواندن، با خیریه، با ساختن بیمارستانی در ملک ورونسکی پر کند؛ اما هیچ چیز پرش نمی‌کند، چون هیچ چیز نمی‌تواند جایگزین آنچه از دست داده شود."),
            StoryParagraph("She misses her son with a physical ache that nothing can soothe; she writes to him, but Karenin forbids any communication; she goes to see him, but Karenin forbids any visit.", "پسرش را با دردی جسمی که هیچ چیز تسکینش نمی‌دهد از دست می‌دهد؛ به او نامه می‌نویسد اما کارنین هر ارتباطی را ممنوع می‌کند؛ به دیدنش می‌رود اما کارنین هر ملاقاتی را ممنوع می‌کند."),
            StoryParagraph("On the day of Seryozha's birthday, Anna sneaks into the house where she once lived, and she holds her son for a few minutes before she is discovered and forced to leave.", "روز تولد سریوژا، آنا دزدانه به خانه‌ای که زمانی در آن زندگی می‌کرد وارد می‌شود و پسرش را چند دقیقه در آغوش می‌گیرد قبل از اینکه کشف شود و مجبور به رفتن شود."),
            StoryParagraph("This scene, one of the most heartbreaking in all of literature, reveals the depth of Anna's loss; she has given up everything, and the one thing she wants most is the one thing she cannot have.", "این صحنه، یکی از دل‌خراش‌ترین صحنه‌های تمام ادبیات، عمق فقدان آنا را آشکار می‌کند؛ همه چیز را فدا کرده و تنها چیزی که بیشتر از همه می‌خواهد، تنها چیزی است که نمی‌تواند داشته باشد."),
            StoryParagraph("Her relationship with Vronsky deteriorates; she becomes jealous, possessive, demanding, and he becomes distant, cold, resentful.", "رابطه‌اش با ورونسکی بدتر می‌شود؛ حسود می‌شود، مالک‌طلب، پرتوقع و او می‌شود دور، سرد، دلخور."),
            StoryParagraph("She has given up everything for him, and she needs him to acknowledge that sacrifice, to make it meaningful, to justify it; but he cannot, because he has not made the same sacrifice.", "او همه چیز را برای او فدا کرده و نیاز دارد او آن فداکاری را به رسمیت بشناسد، معنادارش کند، توجیهش کند؛ اما نمی‌تواند، چون همان فداکاری را نکرده است."),
            StoryParagraph("They begin to fight about small things — about where to live, about whether to go to the opera, about how to spend the evening — and each fight is really about something larger.", "شروع می‌کنند به دعوا بر سر چیزهای کوچک — درباره کجا زندگی کردن، درباره رفتن یا نرفتن به اپرا، درباره چگونه گذراندن شب — و هر دعوا در واقع درباره چیز بزرگ‌تری است."),
            StoryParagraph("Vronsky wants freedom; Anna wants security. Vronsky wants to live his life; Anna wants a life worth living. And neither can give the other what they need.", "ورونسکی آزادی می‌خواهد؛ آنا امنیت. ورونسکی می‌خواهد زندگی‌اش را بکند؛ آنا زندگی‌ای می‌خواهد که ارزش زیستن داشته باشد. و هیچ‌کدام نمی‌توانند آنچه را دیگری نیاز دارد به او بدهند."),
            StoryParagraph("Vronsky's mother, who had at first accepted Anna for her son's sake, now turns against her, and her hostility spreads through the small circle of those who still receive them.", "مادر ورونسکی که ابتدا آنا را به خاطر پسرش پذیرفته بود، حالا علیه‌اش می‌شود و خصومتش در حلقه کوچک کسانی که هنوز می‌پذیرندشان پخش می‌شود."),
            StoryParagraph("Anna becomes, in the eyes of society, a fallen woman; and society, which had once admired her, now despises her, and the despising is worse than the losing.", "آنا در چشمان جامعه زنی افتاده می‌شود؛ و جامعه که زمانی تحسینش می‌کرد، حالا تحقیرش می‌کند و تحقیر بدتر از باختن است."),
            StoryParagraph("She begins to use morphine to sleep, and the morphine, like everything else in her life, becomes a trap from which she cannot escape.", "شروع می‌کند به استفاده از مورفین برای خواب و مورفین، مثل هر چیز دیگری در زندگی‌اش، تله‌ای می‌شود که نمی‌تواند از آن بگریزد."),
            StoryParagraph("She has nightmares — nightmares of Karenin, nightmares of Seryozha, nightmares of Vronsky abandoning her — and she wakes from them drenched in sweat, unable to distinguish the dream from the reality.", "کابوس می‌بیند — کابوس کارنین، کابوس سریوژا، کابوس رهاشدن توسط ورونسکی — و از آنها غرق عرق بیدار می‌شود، ناتوان از تشخیص رؤیا از واقعیت."),
            StoryParagraph("Vronsky, whose love has cooled, begins to spend more time away from her; he goes to his club, he visits his mother, he attends to his business affairs.", "ورونسکی که عشقش سرد شده، شروع می‌کند به گذراندن زمان بیشتری دور از او؛ به باشگاهش می‌رود، به دیدن مادرش، به رسیدگی به امور کاری‌اش."),
            StoryParagraph("Each absence, however innocent, feeds Anna's jealousy; each jealousy, however justified, drives Vronsky further away; and so the cycle continues, downward, accelerating.", "هر غیبت، هرقدر هم بی‌گناه، حسادت آنا را تغذیه می‌کند؛ هر حسادت، هرقدر هم موجه، ورونسکی را بیشتر دور می‌کند؛ و اینگونه چرخه ادامه می‌یابد، رو به پایین، با شتاب."),
            StoryParagraph("This is the trap at the heart of Anna Karenina: that the very love that brought them together is the thing that is tearing them apart, and that neither can stop it.", "این همان تله در قلب آنا کارنیناست: همان عشقی که آنها را به هم آورد، همان چیزی است که آنها را از هم می‌درد و هیچ‌کدام نمی‌توانند متوقفش کنند."),
            StoryParagraph("Anna, who had once been so vital, so warm, so alive, becomes hollow; her beauty fades, her charm fades, her vitality fades, and what remains is only the hunger.", "آنا که زمانی آنقدر پرسرزندگی، گرم، زنده بود، توخالی می‌شود؛ زیبایی‌اش محو می‌شود، جذابیتش محو می‌شود، سرزندگی‌اش محو می‌شود و آنچه می‌ماند فقط گرسنگی است."),
            StoryParagraph("She reads novels in which women sacrifice everything for love, and she wonders why her own sacrifice has not been rewarded as theirs were.", "رمان‌هایی می‌خواند که در آنها زنان همه چیز را برای عشق فدا می‌کنند و از خودش می‌پرسد چرا فداکاری خودش مانند آنها پاداش نگرفته."),
            StoryParagraph("She wonders, in her darker moments, whether she has made a terrible mistake; but she cannot go back, because there is nothing to go back to.", "در لحظات تاریک‌ترش از خودش می‌پرسد آیا اشتباه هولناکی کرده؛ اما نمی‌تواند برگردد، چون چیزی برای بازگشت نیست."),
            StoryParagraph("Karenin, meanwhile, has moved on; he has found a new role, a new purpose, a new identity, in the religious enthusiasm of a certain Countess Lydia Ivanovna.", "کارنین در همین حال راه افتاده؛ نقش جدیدی یافته، هدف جدیدی، هویت جدیدی، در شور و شوق مذهبی کنتس لیدیا ایوانوونا خاصی."),
            StoryParagraph("He forgives Anna — or rather, he tells everyone that he has forgiven her, which is not the same thing — and in doing so, he makes himself appear magnanimous while ensuring that Anna will never be able to return.", "آنا را می‌بخشد — یا بهتر بگوییم، به همه می‌گوید که بخشیده — که همان چیز نیست — و با این کار، خودش را بزرگ‌منش نشان می‌دهد در حالی که تضمین می‌کند آنا هرگز نمی‌تواند برگردد."),
            StoryParagraph("The divorce, which Anna and Vronsky both want, proves impossible to obtain; Karenin refuses it, partly out of spite, partly out of principle, and partly because the law is on his side.", "طلاقی که آنا و ورونسکی هر دو می‌خواهند، غیرممکن می‌شود؛ کارنین ردش می‌کند، تا حدی از کینه، تا حدی از اصول و تا حدی چون قانون طرف اوست."),
            StoryParagraph("Without divorce, Anna cannot marry Vronsky; without marriage, she cannot claim his name, his property, his future; without these, she is trapped.", "بدون طلاق، آنا نمی‌تواند با ورونسکی ازدواج کند؛ بدون ازدواج، نمی‌تواند نامش، دارایی‌اش، آینده‌اش را ادعا کند؛ بدون اینها، گرفتار است."),
            StoryParagraph("She is trapped in a love without a future, trapped in a present that is unbearable, trapped in a past that cannot be undone.", "او در عشقی بدون آینده گرفتار است، در حالی که غیرقابل تحمل است، در گذشته‌ای که نمی‌شود بازش گرداند."),
            StoryParagraph("And in this trap, the thought that has been lurking at the edges of her consciousness finally crystallizes: the thought of death.", "و در این تله، فکری که در لبه‌های هوشیاری‌اش کمین کرده بود، بالاخره متبلور می‌شود: فکر مرگ."),
            StoryParagraph("Not the thought of death as escape, but death as solution, death as the only way out of a problem that has no other answer.", "نه فکر مرگ به عنوان فرار، بلکه مرگ به عنوان راه‌حل، مرگ به عنوان تنها راه خروج از مشکلی که پاسخ دیگری ندارد."),
            StoryParagraph("She begins to imagine it, to plan it, to rehearse it; and as she rehearses, she finds a kind of peace, the peace of a decision that ends all decisions.", "شروع می‌کند به تصورش، نقشه‌اش، تمرینش؛ و در همان حال که تمرین می‌کند، نوعی آرامش می‌یابد، آرامش تصمیمی که همه تصمیمات را پایان می‌دهد.")
        )
    )

    // ─────────── فصل ۵: قطار ───────────
    private fun chapter5() = StoryChapter(
        number = 5, title = "The Train", titlePersian = "قطار",
        paragraphs = listOf(
            StoryParagraph("The final day of Anna's life begins, as such days always do, with an ordinary morning: breakfast, household concerns, a small argument with Vronsky over nothing in particular.", "روز آخر زندگی آنا، همانطور که چنین روزهایی همیشه آغاز می‌شوند، با صبحی معمولی آغاز می‌شود: صبحانه، دغدغه‌های خانه، بحثی کوچک با ورونسکی بر سر هیچ چیز خاصی."),
            StoryParagraph("Vronsky is going to see his mother, who is in town, and Anna has decided — or half-decided, or allowed herself to drift into the decision — that she will follow him.", "ورونسکی می‌رود مادرش را ببیند که در شهر است و آنا تصمیم گرفته — یا نیمه‌تصمیم گرفته، یا اجازه داده خودش را به تصمیم براند — که دنبالش کند."),
            StoryParagraph("She does not know, or will not admit, what she intends; but from the moment she wakes, there is a strange clarity to her thoughts, as if everything has already been decided.", "نمی‌داند، یا نمی‌خواهد اقرار کند، چه قصدی دارد؛ اما از لحظه‌ای که بیدار می‌شود، وضوح عجیبی در افکارش هست، گویی همه چیز قبلاً تصمیم گرفته شده."),
            StoryParagraph("She dresses with unusual care, choosing a white gown that she has not worn in months, and she orders her maid to prepare her things for a journey.", "با دقتی غیرعادی لباس می‌پوشد، لباس سفیدی را انتخاب می‌کند که ماه‌ها نپوشیده و به خدمتکارش دستور می‌دهد وسایلش را برای سفر آماده کند."),
            StoryParagraph("She goes to Vronsky's mother's house, uninvited, unannounced, driven by a jealousy that she knows is irrational but cannot control.", "به خانه مادر ورونسکی می‌رود، ناخوانده، اعلام‌نشده، رانده‌شده توسط حسادتی که می‌داند غیرعقلانی است اما نمی‌تواند کنترلش کند."),
            StoryParagraph("There, she meets a young woman named Sorokina, whom she has seen before, and whom she has — for reasons that have nothing to do with reality — come to hate.", "آنجا، با زن جوانی به نام سوروکینا آشنا می‌شود که قبلاً دیده و به دلایلی که هیچ ربطی به واقعیت ندارد، از او متنفر شده."),
            StoryParagraph("She humiliates herself, in this scene, as only the jealous can humiliate themselves; she speaks too loudly, she laughs too harshly, she makes comments that she will regret for the rest of her life.", "در این صحنه، خودش را تحقیر می‌کند، همانطور که تنها حسودان می‌توانند خودشان را تحقیر کنند؛ بلندتر صحبت می‌کند، سخت‌تر می‌خندد، نظراتی می‌دهد که تا آخر عمر پشیمانشان خواهد بود."),
            StoryParagraph("Vronsky is embarrassed, angry, exhausted; he has been dealing with her moods for months, and he has no more patience for them.", "ورونسکی خجالت‌زده است، خشمگین، خسته؛ ماه‌ها با حالات او سر و کله زده و دیگر صبری برای آنها ندارد."),
            StoryParagraph("'You are behaving impossibly,' he tells her, in a voice that is cold, distant, and utterly without the love that once animated it.", "به او می‌گوید: «داری غیرممکن رفتار می‌کنی» با صدایی که سرد، دور و کاملاً بدون عشقی است که زمانی جانش می‌داد."),
            StoryParagraph("'I am behaving impossibly?' Anna replies, and there is in her voice a note of hysteria, a note of despair, a note of something that is not entirely sane.", "آنا پاسخ می‌دهد: «من غیرممکن رفتار می‌کنم؟» و در صدایش نُتی از هیستری هست، نُتی از ناامیدی، نُتی از چیزی که کاملاً عاقلانه نیست."),
            StoryParagraph("'I have given up everything for you,' she says, 'and you cannot give me one day, one hour, one moment of your attention?'", "می‌گوید: «من همه چیز را برای تو فدا کرده‌ام و تو نمی‌توانی یک روز، یک ساعت، یک لحظه توجهت را به من بدهی؟»"),
            StoryParagraph("'I have given you everything I have,' Vronsky replies, and there is in his voice a note of truth, for he believes it.", "ورونسکی پاسخ می‌دهد: «هر چه داشته‌ام به تو داده‌ام» و در صدایش نُتی از حقیقت هست، چون باورش دارد."),
            StoryParagraph("'Not everything,' Anna says, and her voice is quiet now, and terrible. 'Not your freedom. Not your future. Not your name. You have given me nothing that you would not have given any woman.'", "آنا می‌گوید: «نه همه چیز» و صدایش حالا آرام است و هولناک. «نه آزادی‌ات. نه آینده‌ات. نه نامت. تو هیچ چیزی به من نداده‌ای که به هر زنی نمی‌دادی.»"),
            StoryParagraph("The scene ends, as such scenes do, without resolution; Vronsky leaves, and Anna is left alone with her thoughts, her jealousy, her despair.", "صحنه، همانطور که چنین صحنه‌هایی می‌شوند، بدون حل پایان می‌یابد؛ ورونسکی می‌رود و آنا با افکارش، حسادتش، ناامیدی‌اش تنها می‌ماند."),
            StoryParagraph("She goes to the station, planning to take the train to the country, planning to leave Vronsky, planning — though she will not admit it — to do something more terrible.", "به ایستگاه می‌رود، قصد دارد با قطار به روستا برود، قصد دارد ورونسکی را ترک کند، قصد دارد — هرچند اقرار نخواهد کرد — کار هولناک‌تری بکند."),
            StoryParagraph("At the station, she sends him a note, a note full of reproach, a note that is really a cry for help, a note that he will read too late.", "در ایستگاه، یادداشتی برایش می‌فرستد، یادداشتی پر از سرزنش، یادداشتی که در واقع فریاد کمک است، یادداشتی که او دیر خواهد خواند."),
            StoryParagraph("She waits for his reply, and as she waits, the noise of the station, the movement of the crowd, the whistle of the trains, all seem to fade into a distant hum.", "منتظر پاسخش می‌ماند و در حال انتظار، سر و صدای ایستگاه، حرکت جمعیت، سوت قطارها، همه به همهمه‌ای دور محو می‌شوند."),
            StoryParagraph("She remembers a man who threw himself under a train, years ago, on a day very like this one, and she remembers thinking, at the time, that it was a terrible way to die.", "به یاد مردی می‌افتد که سال‌ها پیش، در روزی بسیار شبیه این، خودش را زیر قطار انداخته بود و به یاد می‌آورد که آن موقع فکر کرده بود روش هولناکی برای مردن است."),
            StoryParagraph("And now, standing on the platform, waiting for Vronsky's reply, she thinks of it again, and she thinks: yes, this is the way.", "و حالا، ایستاده روی سکو، منتظر پاسخ ورونسکی، دوباره به آن فکر می‌کند و فکر می‌کند: بله، این راه است."),
            StoryParagraph("She walks to the edge of the platform, and she looks down at the rails, and she sees herself, as if from outside, as if she were a character in a novel that she is reading.", "به لبه سکو می‌رود و به ریل‌ها نگاه می‌کند و خودش را می‌بیند، گویی از بیرون، گویی شخصیتی است در رمانی که دارد می‌خواند."),
            StoryParagraph("'There,' she thinks, 'is the answer. The only answer. The answer to everything.'", "فکر می‌کند: «آن، پاسخ است. تنها پاسخ. پاسخ به همه چیز.»"),
            StoryParagraph("She crosses herself — an instinct from childhood, from a faith she thought she had lost — and she steps forward, into the path of the oncoming train.", "صلیب می‌کشد — غریزه‌ای از کودکی، از ایمانی که فکر می‌کرد از دست داده — و قدم به جلو می‌گذارد، به مسیر قطاری که می‌آید."),
            StoryParagraph("And in that moment, in the last instant of her life, she feels a flash of terrible regret; she wants to live, she wants to live, she wants to live.", "و در آن لحظه، در آخرین آن زندگی‌اش، جرقه‌ای از پشیمانی هولناک را حس می‌کند؛ می‌خواهد زندگی کند، می‌خواهد زندگی کند، می‌خواهد زندگی کند."),
            StoryParagraph("But it is too late; the train is upon her, and Anna Karenina, who was so alive, who loved so deeply, who suffered so terribly, is no more.", "اما دیر شده؛ قطار رویش است و آنا کارنینا، که اینقدر زنده بود، اینقدر عمیق عشق ورزید، اینقدر هولناک رنج کشید، دیگر نیست."),
            StoryParagraph("Vronsky arrives minutes later, his reply in his hand, his heart full of the reconciliation that he has just decided to offer her; and he finds, instead of Anna, only the crowd.", "ورونسکی دقایقی بعد می‌رسد، پاسخش در دستش، قلبش پر از آشتی‌ای که همین حالا تصمیم گرفته به او عرضه کند؛ و به جای آنا، فقط جمعیت را می‌یابد."),
            StoryParagraph("When he learns what has happened, when he understands that she has done what she has done because of him, because of his coldness, because of his abandonment, he is destroyed.", "وقتی می‌فهمد چه شده، وقتی می‌فهمد او کاری که کرده را به خاطر او کرده، به خاطر سردی‌اش، به خاطر رهایش، نابود می‌شود."),
            StoryParagraph("He volunteers for the Serbian war, hoping to die, hoping to find in battle the death that Anna found under the train.", "داوطلب جنگ صربستان می‌شود، به امید مردن، به امید یافتن در جنگ همان مرگی که آنا زیر قطار یافت."),
            StoryParagraph("But he does not die; he lives on, haunted, hollowed, a man who has lost the only woman he ever loved, and who knows that he lost her not through malice but through weakness.", "اما نمی‌میرد؛ زنده می‌ماند، تسخیرشده، توخالی، مردی که تنها زنی که تا حالا دوست داشت را از دست داده و می‌داند که نه از بدخواهی بلکه از ضعف از دستش داده."),
            StoryParagraph("This is the ending that Tolstoy gives us: not the ending of a story, but the ending of a life, and through it, the ending of a vision of love that was never meant to survive in the world that produced it.", "این پایانی است که تولستوی به ما می‌دهد: نه پایان یک داستان، بلکه پایان یک زندگی و از طریق آن، پایان بینشی از عشق که هرگز قرار نبود در دنیایی که ایجادش کرد زنده بماند."),
            StoryParagraph("Anna Karenina dies because the world will not let her live as she wants to live, because love in her world is a trap not a freedom, because the very vitality that made her beautiful made her dangerous.", "آنا کارنینا می‌میرد چون دنیا نمی‌گذارد آنطور که می‌خواهد زندگی کند، چون عشق در دنیای او تله است نه آزادی، چون همان سرزندگی که او را زیبا می‌کرد، خطرناکش می‌کرد."),
            StoryParagraph("And in her death, Tolstoy indicts not Anna but the world that killed her: a world of surfaces, of proprieties, of cold men and colder women, a world that has no place for a woman who feels too much.", "و در مرگ او، تولستوی نه آنا بلکه دنیایی را متهم می‌کند که او را کشت: دنیایی از سطوح، از آبروها، از مردان سرد و زنان سردتر، دنیایی که جایی برای زنی که بیش از حد احساس می‌کند ندارد."),
            StoryParagraph("The novel does not end here, of course; there is still Levin's story to complete, still the search for meaning that Anna never found, still the hope that somehow, somewhere, there is an answer.", "البته رمان اینجا تمام نمی‌شود؛ هنوز داستان لوین هست که کامل شود، هنوز جستجوی معنا که آنا هرگز نیافت، هنوز امید به اینکه جایی، به نحوی، پاسخی هست."),
            StoryParagraph("But Anna's story ends here, and with it ends the most beautiful and most terrible portrait of a woman in all of literature.", "اما داستان آنا اینجا تمام می‌شود و با آن، زیباترین و هولناک‌ترین تصویر یک زن در تمام ادبیات پایان می‌یابد.")
        )
    )

    // ─────────── فصل ۶: پایان ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "The End", titlePersian = "پایان",
        paragraphs = listOf(
            StoryParagraph("After Anna's death, the novel continues for another hundred pages, and these hundred pages are essential to understanding what Tolstoy was trying to say.", "پس از مرگ آنا، رمان صد صفحه دیگر ادامه می‌یابد و این صد صفحه برای فهم آنچه تولستوی می‌خواست بگوید اساسی است."),
            StoryParagraph("Levin, who has been living in the countryside with Kitty and their young son, is still tormented by the questions that have haunted him from the beginning.", "لوین که در روستا با کیتی و پسر کوچکشان زندگی می‌کند، هنوز توسط پرسش‌هایی که از ابتدا تسخیرش کرده بودند عذاب می‌کشد."),
            StoryParagraph("He has everything a man could want: a loving wife, healthy children, a successful estate, the respect of his community.", "او هر چیزی را دارد که یک مرد می‌تواند بخواهد: همسری دوستدار، فرزندانی سالم، ملکی موفق، احترام جامعه‌اش."),
            StoryParagraph("And yet, he is not at peace. The questions remain. Why are we here? What is the meaning of life? How should we live?", "و با این حال، در آرامش نیست. پرسش‌ها باقی می‌مانند. چرا اینجاییم؟ معنای زندگی چیست؟ چگونه باید زندگی کنیم؟"),
            StoryParagraph("He reads, he thinks, he argues with himself; he tries to believe in God, then doubts, then tries again, then doubts again.", "می‌خواند، فکر می‌کند، با خودش بحث می‌کند؛ تلاش می‌کند به خدا باور کند، بعد شک می‌کند، بعد دوباره تلاش می‌کند، بعد دوباره شک می‌کند."),
            StoryParagraph("His faith, if it can be called faith, is a faith of doubt: it is the faith of a man who cannot believe but who cannot stop hoping, who cannot be certain but who cannot stop searching.", "ایمانش، اگر بتوان ایمان نامیدش، ایمان شک است: ایمان مردی است که نمی‌تواند باور کند اما نمی‌تواند امید را رها کند، نمی‌تواند مطمئن باشد اما نمی‌تواند جستجو را رها کند."),
            StoryParagraph("And then, one day, in the middle of an ordinary moment — a conversation with a peasant about whether a man should kill a wolf, of all things — Levin has a revelation.", "و بعد، یک روز، در میانه لحظه‌ای معمولی — گفتگویی با دهقانی درباره اینکه آیا انسان باید گرگی را بکشد، از همه چیز — لوین مکاشفه‌ای دارد."),
            StoryParagraph("He realizes, in that moment, that the meaning of life is not something to be discovered by the intellect, but something to be lived by the whole person.", "در آن لحظه می‌فهمد که معنای زندگی چیزی نیست که توسط عقل کشف شود، بلکه چیزی است که توسط تمام شخص زندگی شود."),
            StoryParagraph("The peasant, who has never read a book, who has never asked a philosophical question, who simply lives and works and loves, knows how to live; and Levin, who has read every book and asked every question, does not.", "دهقانی که هرگز کتابی نخوانده، هرگز پرسش فلسفی نپرسیده، فقط زندگی می‌کند و کار می‌کند و عشق می‌ورزد، می‌داند چگونه زندگی کند؛ و لوین که هر کتابی خوانده و هر پرسشی پرسیده، نمی‌داند."),
            StoryParagraph("'I have been searching for a miracle,' Levin thinks, 'and the miracle is all around me. It is in the sky, in the earth, in the simple faith of the peasants. I have only been too blind to see it.'", "لوین فکر می‌کند: «دنبال معجزه‌ای بوده‌ام و معجزه همه‌جا دور من است. در آسمان، در زمین، در ایمان ساده دهقانان است. فقط بیش از حد کور بوده‌ام که ببینمش.»"),
            StoryParagraph("This revelation does not solve Levin's problems; it does not answer his questions; it does not give him certainty, or peace, or closure.", "این مکاشفه مشکلات لوین را حل نمی‌کند؛ پرسش‌هایش را پاسخ نمی‌دهد؛ قطعیت، آرامش یا نتیجه‌گیری به او نمی‌دهد."),
            StoryParagraph("It simply gives him the courage to live without certainty, to ask without expecting answers, to search without expecting to find.", "فقط به او جرات زندگی کردن بدون قطعیت می‌دهد، پرسیدن بدون انتظار پاسخ، جستجو بدون انتظار یافتن."),
            StoryParagraph("And this courage, this terrible, beautiful, human courage, is what Tolstoy offers us as the answer to the novel's central question.", "و این جرات، این جرات هولناک، زیبا، انسانی، چیزی است که تولستوی به عنوان پاسخ به پرسش اصلی رمان به ما عرضه می‌کند."),
            StoryParagraph("Not a rule, not a doctrine, not a philosophy; but a way of being in the world that accepts the mystery without trying to solve it.", "نه قاعده‌ای، نه عقیده‌ای، نه فلسفه‌ای؛ بلکه شیوه‌ای از بودن در دنیا که رمز را می‌پذیرد بی‌آنکه تلاش کند حلش کند."),
            StoryParagraph("Levin's last thought, in the novel, is this: 'My life is not a mistake. It is not a failure. It is a mystery, and I will live it.'", "آخرین فکر لوین در رمان این است: «زندگی‌ام اشتباه نیست. شکست نیست. رمزی است و آن را زندگی خواهم کرد.»"),
            StoryParagraph("And this, in Tolstoy's vision, is the greatest wisdom available to any human being: to accept that we cannot know, and to live anyway.", "و این، در بینش تولستوی، بزرگ‌ترین حکمتی است که برای هر انسانی در دسترس است: پذیرش اینکه نمی‌توانیم بدانیم و به هر حال زندگی کنیم."),
            StoryParagraph("Anna chose certainty, and certainty killed her; Levin chose mystery, and mystery saved him.", "آنا قطعیت را انتخاب کرد و قطعیت او را کشت؛ لوین رمز را انتخاب کرد و رمز او را نجات داد."),
            StoryParagraph("Not that Anna is condemned and Levin is praised; Tolstoy does not make such simple judgments. He simply shows us what happens, and lets us decide what to make of it.", "نه اینکه آنا محکوم و لوین تحسین شود؛ تولستوی چنین قضاوت‌های ساده‌ای نمی‌کند. او فقط به ما نشان می‌دهد چه اتفاقی می‌افتد و می‌گذارد خودمان تصمیم بگیریم از آن چه بسازیم."),
            StoryParagraph("And what we make of it, what we have always made of it, is this: that life is not a problem to be solved but a gift to be received.", "و آنچه از آن می‌سازیم، آنچه همیشه از آن ساخته‌ایم، این است: زندگی مسئله‌ای نیست که حل شود بلکه موهبتی است که دریافت شود."),
            StoryParagraph("That love is not a possession to be hoarded but a gift to be given; that happiness is not a destination to be reached but a way of traveling.", "عشق مالکیتی نیست که انباشته شود بلکه موهبتی است که داده شود؛ خوشبختی مقصدی نیست که رسیده شود بلکه شیوه‌ای از سفر است."),
            StoryParagraph("And that the meaning of life, if it exists at all, is not to be found in books or arguments or theories, but in the simple, daily, unglamorous act of living.", "و اینکه معنای زندگی، اگر اصلاً وجود داشته باشد، نه در کتاب‌ها یا استدلال‌ها یا نظریه‌ها یافت می‌شود، بلکه در عمل ساده، روزانه، بی‌جذابیت زندگی کردن."),
            StoryParagraph("Tolstoy wrote Anna Karenina over a period of five years, and in the writing of it, he transformed both himself and the novel as a form.", "تولستوی آنا کارنینا را در طول پنج سال نوشت و در نوشتنش، هم خودش و هم رمان را به عنوان یک فرم دگرگون کرد."),
            StoryParagraph("He created, in this novel, something that had never existed before: a work of fiction that is also a work of philosophy, a story that is also a sermon, a tragedy that is also a gospel.", "او در این رمان چیزی خلق کرد که قبلاً وجود نداشت: اثری داستانی که اثری فلسفی هم هست، داستانی که موعظه هم هست، تراژدی‌ای که انجیل هم هست."),
            StoryParagraph("And in creating this, he created something that has lasted: a novel that speaks to every generation because it speaks to every human being.", "و در خلق این، چیزی آفرید که دوام یافته: رمانی که با هر نسلی صحبت می‌کند چون با هر انسانی صحبت می‌کند."),
            StoryParagraph("Anna Karenina is not about Russia in the 1870s; it is about the human heart, in every time and every place.", "آنا کارنینا درباره روسیه دهه ۱۸۷۰ نیست؛ درباره قلب انسان است، در هر زمان و هر مکان."),
            StoryParagraph("It is about the impossible demands we make of love, and the impossible demands love makes of us.", "درباره خواسته‌های غیرممکنی است که از عشق می‌کنیم و خواسته‌های غیرممکنی که عشق از ما می‌کند."),
            StoryParagraph("It is about the way we destroy what we love most, sometimes because we love it too much, sometimes because we love it too little.", "درباره شیوه‌ای است که ما آنچه را بیش از همه دوست داریم نابود می‌کنیم، گاهی چون بیش از حد دوستش داریم، گاهی چون کم دوستش داریم."),
            StoryParagraph("It is about the impossibility of happiness and the necessity of hoping for it anyway.", "درباره غیرممکن بودن خوشبختی و ضرورت امید بستن به آن به هر حال."),
            StoryParagraph("And it is about the terrible, beautiful, unbearable fact of being alive, of being human, of being caught between the heaven we imagine and the earth we inhabit.", "و درباره واقعیت هولناک، زیبا، غیرقابل تحمل زنده بودن است، انسان بودن، گرفتار بودن میان بهشتی که تصور می‌کنیم و زمینی که سکنی داریم."),
            StoryParagraph("This is what Tolstoy gives us: not an answer, but a question; not a destination, but a journey; not a conclusion, but an invitation.", "این چیزی است که تولستوی به ما می‌دهد: نه پاسخ، بلکه پرسش؛ نه مقصد، بلکه سفر؛ نه نتیجه‌گیری، بلکه دعوت."),
            StoryParagraph("The invitation is this: to read the novel, to enter into its world, to live with its characters, to suffer with them, to hope with them.", "دعوت این است: رمان را بخوانیم، به دنیایش وارد شویم، با شخصیت‌هایش زندگی کنیم، با آنها رنج بکشیم، با آنها امید ببندیم."),
            StoryParagraph("And when we close the book, to return to our own lives with a new awareness: that we are all, in some sense, Anna; and that we are all, in some sense, Levin; and that the choice between them is the choice that every human being must make.", "و وقتی کتاب را می‌بندیم، به زندگی خودمان با آگاهی جدیدی بازگردیم: که همه‌مان به نوعی آنا هستیم؛ و همه‌مان به نوعی لوین؛ و انتخاب میان آنها همان انتخابی است که هر انسانی باید بکند."),
            StoryParagraph("Not once, but every day. Not easily, but necessarily. Not with certainty, but with hope.", "نه یک بار، بلکه هر روز. نه به آسانی، بلکه به ضرورت. نه با قطعیت، بلکه با امید."),
            StoryParagraph("And in that daily choice, in that daily hope, in that daily willingness to live without knowing why, is found the only happiness that is available to us in this life.", "و در آن انتخاب روزانه، در آن امید روزانه، در آن آمادگی روزانه برای زندگی بدون دانستن چرا، تنها خوشبختی‌ای یافت می‌شود که در این زندگی برای ما در دسترس است."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("Or perhaps: the beginning.", "یا شاید: آغاز.")
        )
    )
}